        runs = []
        cur = ''
        for ch in s:
            if '0' <= ch <= '9':
                cur += ch
            elif cur:
                runs.append(cur)
                cur = ''
        if cur:
            runs.append(cur)
        a, b, c = runs
        if len(a) == 4:
            y, m, d = int(a), int(b), int(c)
        else:
            m, d, y = int(a), int(b), int(c)
