def gen(rng):
    SEP = '_/-.:,;|#*+~@%^&!=?'
    dm = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    def days(y, m):
        leap = y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
        return dm[m - 1] + (1 if m == 2 and leap else 0)
    def field(v, L):
        return str(v).zfill(L)
    def sepstr(k, same):
        if same:
            return rng.choice(SEP) * k
        return ''.join(rng.choice(SEP) for _ in range(k))
    def make(y, m, d, yfirst):
        la = 2 if m >= 10 else rng.choice((1, 2))
        lb = 2 if d >= 10 else rng.choice((1, 2))
        total = 10 - (4 + la + lb)
        s1 = rng.randint(1, total - 1)
        s2 = total - s1
        same = rng.random() < 0.6
        a, b = sepstr(s1, same), sepstr(s2, same)
        ys = field(y, 4)
        ms, ds = field(m, la), field(d, lb)
        if yfirst:
            return ys + a + ms + b + ds
        return ms + a + ds + b + ys
    def rand_item():
        yfirst = rng.random() < 0.5
        if rng.random() < 0.55:
            y = rng.choice((rng.randint(1, 9999), rng.randint(1900, 2100), 2000, 1900, 2024, 2023))
            m = rng.randint(1, 12)
            d = rng.randint(1, days(y, m))
            if m == 2 and rng.random() < 0.3:
                d = days(y, m)
        else:
            y = rng.choice((rng.randint(0, 9999), rng.randint(1900, 2100)))
            m = rng.randint(0, 14)
            d = rng.randint(0, 33)
            if rng.random() < 0.4:
                m = rng.randint(1, 12)
                d = days(max(y, 1), m) + rng.choice((1, 1, 2))
                d = min(d, 99)
        return make(y, m, d, yfirst)
    def fmt(items):
        return str(len(items)) + '\n' + '\n'.join(items)
    tests = [fmt(['2024_03_15', '03/15/2024', '2024__2__9']), fmt(['02/30/2023', '2024.02.29', '2023.02.29', '13--1-2020'])]
    tests.append(fmt([make(2000, 2, 29, True), make(1900, 2, 29, True), make(2100, 2, 29, False), make(2400, 2, 29, False), make(1, 1, 1, True), make(1, 1, 1, False), make(0, 1, 1, True), make(9999, 12, 31, True)]))
    tests.append(fmt([make(2023, 4, 31, True), make(2023, 4, 30, True), make(2023, 0, 5, True), make(2023, 5, 0, False), make(2023, 12, 32, True), make(2023, 13, 1, False), make(2023, 6, 15, False), make(2023, 11, 31, False)]))
    tests.append(fmt([make(2020, 1, 1, False), make(2020, 1, 1, True)]))
    tests.append(fmt([make(2024, 2, 9, True)]))
    for q in (1, 2, 3, 5, 8, 12, 20, 25):
        for _ in range(2):
            tests.append(fmt([rand_item() for _ in range(q)]))
    Q = 100000
    for _ in range(3):
        tests.append(fmt([rand_item() for _ in range(Q)]))
    return tests

